printf '%s\n' 'apiVersion: apps/v1' 'kind: Deployment' 'metadata:' '  name: {{ .Release.Name }}' 'spec:' '  replicas: {{ .Values.replicaCount }}' '  selector:' '    matchLabels:' '      app: {{ .Release.Name }}' '  template:' '    metadata:' '      labels:' '        app: {{ .Release.Name }}' '    spec:' '      containers:' '        - name: web' '          image: "{{ .Values.image.repository }}:{{ .Values.image.tag | default .Chart.AppVersion }}"' '          ports:' '            - containerPort: {{ .Values.service.port }}' > shop/templates/deployment.yaml
